def solution(n, edges):
    parent = list(range(n))   # each machine starts as its own root
    size = [1] * n

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]   # path halving keeps trees flat
            x = parent[x]
        return x

    count = n
    for a, b in edges:
        ra, rb = find(a), find(b)
        if ra == rb:
            continue              # already in one cluster (repeat, cycle or self-cable)
        if size[ra] < size[rb]:
            ra, rb = rb, ra
        parent[rb] = ra           # hang the smaller tree under the bigger
        size[ra] += size[rb]
        count -= 1                # two clusters became one
    return count

