def solution(n, edges):
    # Relabel: merging two clusters rewrites every label of one of them.
    # Each merge scans all n machines: O(n * E).
    label = list(range(n))
    for a, b in edges:
        la, lb = label[a], label[b]
        if la == lb:
            continue
        for i in range(n):
            if label[i] == lb:
                label[i] = la
    return len(set(label))
